<?php
namespace App\Services;
use Illuminate\Support\Arr;
use Illuminate\Support\Str;
use OpenAI\Laravel\Facades\OpenAI;
use RuntimeException;
class SiteSeoAiService { public function generate(): array { if (blank(config('openai.api_key'))) throw new RuntimeException('OPENAI_API_KEY is not configured.'); $response=OpenAI::chat()->create(['model'=>config('openai.seo_model','gpt-4o-mini'),'temperature'=>0.25,'response_format'=>['type'=>'json_object'],'messages'=>[['role'=>'system','content'=>'You are an SEO editor for City Phones, a Saudi electronics ecommerce store. Return JSON only. Never invent awards, prices, guarantees, or business facts. Write native Saudi Arabic and natural English.'],['role'=>'user','content'=>json_encode(['task'=>'Generate homepage SEO metadata. Arabic and English titles: 30-70 chars. Descriptions: 110-170 chars. Keywords: concise comma-separated list.','required_json'=>['seo_home_title_ar','seo_home_title_en','seo_home_description_ar','seo_home_description_en','seo_home_keywords_ar','seo_home_keywords_en','seo_business_name_ar','seo_business_name_en']],JSON_UNESCAPED_UNICODE)]]]); $data=json_decode((string)$response->choices[0]->message->content,true); if(!is_array($data)) throw new RuntimeException('OpenAI returned an invalid SEO response.'); return collect(['seo_home_title_ar'=>70,'seo_home_title_en'=>70,'seo_home_description_ar'=>170,'seo_home_description_en'=>170,'seo_home_keywords_ar'=>500,'seo_home_keywords_en'=>500,'seo_business_name_ar'=>120,'seo_business_name_en'=>120])->mapWithKeys(fn($max,$key)=>[$key=>Str::limit(trim((string)Arr::get($data,$key)),$max,'')])->all(); } }